"use client";

import { process, sections } from "@/lib/data";
import { SectionHeading } from "@/components/ui/section-heading";
import { Reveal } from "@/components/motion/reveal";
import { ChevronRight } from "lucide-react";
import { useLang } from "@/components/providers/language-provider";
import { tr } from "@/lib/i18n";

export function Process() {
  const { lang } = useLang();
  const s = sections.process;

  return (
    <section id="process" className="section-padding relative">
      <div className="container">
        <SectionHeading
          index="06"
          eyebrow={tr(s.eyebrow, lang)}
          title={tr(s.title, lang)}
          description={s.description ? tr(s.description, lang) : undefined}
        />

        <div className="mt-14 grid gap-3 md:grid-cols-2 lg:grid-cols-4">
          {process.map((step, i) => (
            <Reveal key={i} delay={i % 4}>
              <div className="relative h-full">
                <div className="card-surface h-full p-6 transition-colors hover:border-accent/30">
                  <div className="flex items-center justify-between">
                    <span className="font-mono text-sm text-muted-foreground/60">
                      {String(i + 1).padStart(2, "0")}
                    </span>
                    <step.icon className="h-5 w-5 text-accent" />
                  </div>
                  <h3 className="mt-4 text-base font-semibold tracking-tight">
                    {tr(step.title, lang)}
                  </h3>
                  <p className="mt-2 text-sm leading-relaxed text-muted-foreground">
                    {tr(step.description, lang)}
                  </p>
                </div>
                {i < process.length - 1 && (
                  <ChevronRight
                    className="absolute -right-3 top-1/2 hidden h-5 w-5 -translate-y-1/2 text-muted-foreground/30 lg:block"
                    aria-hidden
                  />
                )}
              </div>
            </Reveal>
          ))}
        </div>
      </div>
    </section>
  );
}
