"use client";

import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import {
  Github,
  ArrowUpRight,
  ChevronDown,
  Target,
  Lightbulb,
  Layers,
  Cpu,
  TrendingUp,
  GraduationCap,
  Info,
} from "lucide-react";
import type { Project } from "@/lib/data";
import { ui } from "@/lib/data";
import { Badge } from "@/components/ui/badge";
import { useLang } from "@/components/providers/language-provider";
import { tr, trList } from "@/lib/i18n";
import { cn } from "@/lib/utils";

export function ProjectCard({ project, index }: { project: Project; index: number }) {
  const { lang } = useLang();
  const [open, setOpen] = useState(false);

  const detailBlocks = [
    { icon: Target, label: tr(ui.problem, lang), body: tr(project.problem, lang) },
    { icon: Lightbulb, label: tr(ui.solution, lang), body: tr(project.solution, lang) },
    { icon: Layers, label: tr(ui.architecture, lang), body: tr(project.architecture, lang) },
  ];

  return (
    <motion.article
      initial={{ opacity: 0, y: 28 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true, margin: "-60px" }}
      transition={{ duration: 0.6, delay: (index % 2) * 0.08, ease: [0.21, 0.47, 0.32, 0.98] }}
      className="group relative overflow-hidden rounded-2xl border border-border bg-card transition-colors hover:border-accent/40"
    >
      {/* Subtle single-accent glow */}
      <div
        className="pointer-events-none absolute -right-24 -top-24 h-56 w-56 rounded-full bg-accent/10 opacity-0 blur-3xl transition-opacity duration-500 group-hover:opacity-100"
        aria-hidden
      />

      <div className="relative p-7 sm:p-8">
        <div className="flex flex-wrap items-start justify-between gap-4">
          <div>
            <div className="flex items-center gap-3">
              <h3 className="text-2xl font-semibold tracking-tight">{project.name}</h3>
              {project.featured && <Badge variant="accent">Featured</Badge>}
            </div>
            <div className="mt-2 flex flex-wrap items-center gap-2 text-sm text-muted-foreground">
              <span>{project.year}</span>
              <span className="h-1 w-1 rounded-full bg-muted-foreground/40" />
              <span>{tr(project.status, lang)}</span>
            </div>
          </div>
          <div className="flex items-center gap-2">
            {project.githubUrl && (
              <a
                href={project.githubUrl}
                target="_blank"
                rel="noopener noreferrer"
                aria-label={`${project.name} — GitHub`}
                className="flex h-10 w-10 items-center justify-center rounded-full border border-border bg-background/60 text-foreground transition-colors hover:bg-muted"
              >
                <Github className="h-4 w-4" />
              </a>
            )}
            {project.liveUrl && (
              <a
                href={project.liveUrl}
                target="_blank"
                rel="noopener noreferrer"
                aria-label={`${project.name} — site`}
                className="flex h-10 w-10 items-center justify-center rounded-full border border-border bg-background/60 text-foreground transition-colors hover:bg-muted"
              >
                <ArrowUpRight className="h-4 w-4" />
              </a>
            )}
          </div>
        </div>

        <p className="mt-4 max-w-2xl text-pretty leading-relaxed text-muted-foreground">
          {tr(project.tagline, lang)}
        </p>

        <div className="mt-5 flex flex-wrap gap-2">
          {project.stack.map((s) => (
            <span
              key={s}
              className="rounded-full border border-border bg-background/50 px-3 py-1 text-xs font-medium text-muted-foreground"
            >
              {s}
            </span>
          ))}
        </div>

        <button
          type="button"
          onClick={() => setOpen((v) => !v)}
          aria-expanded={open}
          className="mt-6 inline-flex items-center gap-1.5 text-sm font-medium text-accent transition-colors hover:brightness-110"
        >
          {open ? tr(ui.collapse, lang) : tr(ui.expand, lang)}
          <ChevronDown
            className={cn("h-4 w-4 transition-transform duration-300", open && "rotate-180")}
          />
        </button>

        <AnimatePresence initial={false}>
          {open && (
            <motion.div
              initial={{ height: 0, opacity: 0 }}
              animate={{ height: "auto", opacity: 1 }}
              exit={{ height: 0, opacity: 0 }}
              transition={{ duration: 0.4, ease: [0.21, 0.47, 0.32, 0.98] }}
              className="overflow-hidden"
            >
              <div className="mt-6 space-y-6 border-t border-border pt-6">
                <div className="grid gap-5 sm:grid-cols-3">
                  {detailBlocks.map((b) => (
                    <div key={b.label}>
                      <div className="mb-2 flex items-center gap-2 text-sm font-medium">
                        <b.icon className="h-4 w-4 text-accent" />
                        {b.label}
                      </div>
                      <p className="text-sm leading-relaxed text-muted-foreground">
                        {b.body}
                      </p>
                    </div>
                  ))}
                </div>

                <div className="grid gap-6 sm:grid-cols-2">
                  <div>
                    <div className="mb-3 flex items-center gap-2 text-sm font-medium">
                      <Cpu className="h-4 w-4 text-accent" />
                      {tr(ui.highlights, lang)}
                    </div>
                    <ul className="space-y-2.5">
                      {trList(project.highlights, lang).map((h) => (
                        <li key={h} className="flex gap-2.5 text-sm leading-relaxed text-muted-foreground">
                          <span className="mt-2 h-1.5 w-1.5 flex-shrink-0 rounded-full bg-accent/70" />
                          {h}
                        </li>
                      ))}
                    </ul>
                  </div>
                  <div className="space-y-6">
                    <div>
                      <div className="mb-3 flex items-center gap-2 text-sm font-medium">
                        <TrendingUp className="h-4 w-4 text-accent" />
                        {tr(ui.results, lang)}
                      </div>
                      <ul className="space-y-2.5">
                        {trList(project.results, lang).map((r) => (
                          <li key={r} className="flex gap-2.5 text-sm leading-relaxed text-muted-foreground">
                            <span className="mt-2 h-1.5 w-1.5 flex-shrink-0 rounded-full bg-accent/70" />
                            {r}
                          </li>
                        ))}
                      </ul>
                    </div>
                    <div>
                      <div className="mb-2 flex items-center gap-2 text-sm font-medium">
                        <GraduationCap className="h-4 w-4 text-accent" />
                        {tr(ui.learned, lang)}
                      </div>
                      <p className="text-sm leading-relaxed text-muted-foreground">
                        {tr(project.learned, lang)}
                      </p>
                    </div>
                  </div>
                </div>

                {project.note && (
                  <div className="flex items-start gap-2.5 rounded-xl border border-dashed border-border bg-background/40 p-4 text-sm text-muted-foreground">
                    <Info className="mt-0.5 h-4 w-4 flex-shrink-0 text-accent" />
                    <span>{tr(project.note, lang)}</span>
                  </div>
                )}
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </motion.article>
  );
}
