"use client";

import { githubMeta, site, sections } from "@/lib/data";
import { SectionHeading } from "@/components/ui/section-heading";
import { Reveal } from "@/components/motion/reveal";
import { Counter } from "@/components/motion/counter";
import { Github, Star, ArrowUpRight } from "lucide-react";
import { useLang } from "@/components/providers/language-provider";
import { tr } from "@/lib/i18n";

export function GithubSection() {
  const { lang } = useLang();
  const s = sections.github;

  const labels = {
    repos: { ru: "публичных репозиториев", en: "public repositories" },
    mainLang: { ru: "основной язык", en: "main language" },
    topLangs: { ru: "Основные языки", en: "Top languages" },
  };

  return (
    <section id="github" className="section-padding relative bg-muted/20">
      <div className="container">
        <SectionHeading
          index="09"
          eyebrow={tr(s.eyebrow, lang)}
          title={tr(s.title, lang)}
          description={s.description ? tr(s.description, lang) : undefined}
        />

        <div className="mt-14 grid gap-6 lg:grid-cols-[0.9fr_1.1fr]">
          {/* Stats panel */}
          <Reveal>
            <div className="card-surface flex h-full flex-col justify-between gap-8 p-8">
              <div className="flex items-center gap-3">
                <div className="flex h-12 w-12 items-center justify-center rounded-2xl bg-foreground text-background">
                  <Github className="h-6 w-6" />
                </div>
                <div>
                  <div className="font-semibold">@{site.github}</div>
                  <a
                    href={site.githubUrl}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="inline-flex items-center gap-1 text-sm text-accent hover:brightness-110"
                  >
                    github.com/{site.github}
                    <ArrowUpRight className="h-3.5 w-3.5" />
                  </a>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-6">
                <div>
                  <div className="text-4xl font-semibold tracking-tight">
                    <Counter value={githubMeta.publicRepos} />
                  </div>
                  <div className="mt-1 text-sm text-muted-foreground">
                    {tr(labels.repos, lang)}
                  </div>
                </div>
                <div>
                  <div className="text-4xl font-semibold tracking-tight">Dart</div>
                  <div className="mt-1 text-sm text-muted-foreground">
                    {tr(labels.mainLang, lang)}
                  </div>
                </div>
              </div>

              <div>
                <div className="mb-3 text-xs font-medium uppercase tracking-widest text-muted-foreground/70">
                  {tr(labels.topLangs, lang)}
                </div>
                <div className="flex flex-wrap gap-2">
                  {githubMeta.topLanguages.map((l) => (
                    <span
                      key={l}
                      className="rounded-full border border-border bg-background/50 px-3 py-1 text-xs font-medium text-muted-foreground"
                    >
                      {l}
                    </span>
                  ))}
                </div>
              </div>
            </div>
          </Reveal>

          {/* Featured repos */}
          <div className="grid gap-4 sm:grid-cols-2">
            {githubMeta.featuredRepos.map((repo, i) => (
              <Reveal key={repo.name} delay={i % 2}>
                <a
                  href={`${site.githubUrl}/${repo.name}`}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="group card-surface flex h-full flex-col p-6 transition-all duration-300 hover:-translate-y-1 hover:border-accent/30"
                >
                  <div className="flex items-start justify-between">
                    <div className="flex items-center gap-2 font-mono text-sm font-medium">
                      <Github className="h-4 w-4 text-muted-foreground" />
                      {repo.name}
                    </div>
                    <span className="inline-flex items-center gap-1 text-xs text-muted-foreground">
                      <Star className="h-3.5 w-3.5" />
                      {repo.stars}
                    </span>
                  </div>
                  <p className="mt-3 flex-1 text-sm leading-relaxed text-muted-foreground">
                    {tr(repo.desc, lang)}
                  </p>
                  <div className="mt-4 flex items-center gap-2">
                    <span className="h-2.5 w-2.5 rounded-full bg-accent" />
                    <span className="text-xs text-muted-foreground">{repo.lang}</span>
                  </div>
                </a>
              </Reveal>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
}
