import { Reveal } from "@/components/motion/reveal";
import { cn } from "@/lib/utils";

export function SectionHeading({
  eyebrow,
  title,
  description,
  index,
  align = "left",
  className,
}: {
  eyebrow?: string;
  title: string;
  description?: string;
  index?: string;
  align?: "left" | "center";
  className?: string;
}) {
  return (
    <div
      className={cn(
        "max-w-3xl",
        align === "center" && "mx-auto text-center",
        className
      )}
    >
      {eyebrow && (
        <Reveal>
          <div
            className={cn(
              "mb-5 flex items-baseline gap-3 font-mono text-xs uppercase tracking-[0.25em] text-accent",
              align === "center" && "justify-center"
            )}
          >
            {index && <span className="text-muted-foreground/50">{index}</span>}
            <span className="h-px w-6 translate-y-[-3px] bg-accent/50" aria-hidden />
            <span>{eyebrow}</span>
          </div>
        </Reveal>
      )}
      <Reveal delay={1}>
        <h2 className="text-balance font-semibold tracking-tight text-[clamp(1.9rem,4.5vw,3.25rem)] leading-[1.05]">
          {title}
        </h2>
      </Reveal>
      {description && (
        <Reveal delay={2}>
          <p className="mt-6 max-w-2xl text-pretty text-base leading-relaxed text-muted-foreground sm:text-lg">
            {description}
          </p>
        </Reveal>
      )}
    </div>
  );
}
