"use client";

import { useEffect, useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Menu, X } from "lucide-react";
import { navLinks, site, ui } from "@/lib/data";
import { ThemeToggle } from "./theme-toggle";
import { useLang } from "@/components/providers/language-provider";
import { tr } from "@/lib/i18n";
import { cn } from "@/lib/utils";

function LangToggle() {
  const { lang, toggle } = useLang();
  return (
    <button
      type="button"
      onClick={toggle}
      aria-label={lang === "ru" ? "Switch to English" : "Переключить на русский"}
      className="flex h-10 items-center rounded-full border border-border bg-card/50 px-3 font-mono text-xs font-medium tracking-wider text-muted-foreground transition-colors hover:text-foreground"
    >
      <span className={lang === "ru" ? "text-foreground" : ""}>RU</span>
      <span className="mx-1 text-border">/</span>
      <span className={lang === "en" ? "text-foreground" : ""}>EN</span>
    </button>
  );
}

export function Navbar() {
  const { lang } = useLang();
  const [scrolled, setScrolled] = useState(false);
  const [open, setOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 24);
    onScroll();
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  return (
    <header className="fixed inset-x-0 top-0 z-50">
      <div className="container">
        <nav
          className={cn(
            "mt-4 flex items-center justify-between rounded-full px-4 py-2.5 transition-all duration-500 sm:px-5",
            scrolled
              ? "glass shadow-[0_8px_40px_-12px_rgba(0,0,0,0.5)]"
              : "border border-transparent"
          )}
        >
          <a
            href="#top"
            className="flex items-center gap-2.5 pl-1 font-semibold tracking-tight"
          >
            <span className="flex h-8 w-8 items-center justify-center rounded-lg bg-accent text-sm font-bold text-accent-foreground">
              BS
            </span>
            <span className="hidden sm:inline">{site.name}</span>
          </a>

          <div className="hidden items-center gap-1 md:flex">
            {navLinks.map((link) => (
              <a
                key={link.href}
                href={link.href}
                className="rounded-full px-3.5 py-2 text-sm text-muted-foreground transition-colors hover:text-foreground"
              >
                {tr(link.label, lang)}
              </a>
            ))}
          </div>

          <div className="flex items-center gap-2">
            <LangToggle />
            <ThemeToggle />
            <a
              href="#contact"
              className="hidden h-10 items-center rounded-full bg-foreground px-5 text-sm font-medium text-background transition-transform hover:-translate-y-0.5 sm:inline-flex"
            >
              {tr(ui.message, lang)}
            </a>
            <button
              type="button"
              aria-label={lang === "ru" ? "Меню" : "Menu"}
              aria-expanded={open}
              onClick={() => setOpen((v) => !v)}
              className="flex h-10 w-10 items-center justify-center rounded-full border border-border bg-card/50 md:hidden"
            >
              {open ? <X className="h-5 w-5" /> : <Menu className="h-5 w-5" />}
            </button>
          </div>
        </nav>
      </div>

      <AnimatePresence>
        {open && (
          <motion.div
            initial={{ opacity: 0, y: -8 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -8 }}
            transition={{ duration: 0.2 }}
            className="container md:hidden"
          >
            <div className="glass mt-2 flex flex-col gap-1 rounded-2xl p-3">
              {navLinks.map((link) => (
                <a
                  key={link.href}
                  href={link.href}
                  onClick={() => setOpen(false)}
                  className="rounded-xl px-4 py-3 text-sm text-muted-foreground transition-colors hover:bg-muted hover:text-foreground"
                >
                  {tr(link.label, lang)}
                </a>
              ))}
              <a
                href="#contact"
                onClick={() => setOpen(false)}
                className="mt-1 rounded-xl bg-accent px-4 py-3 text-center text-sm font-medium text-accent-foreground"
              >
                {tr(ui.message, lang)}
              </a>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </header>
  );
}
